/** Fields that need a separate, non-unique lookup index. */
export function filterIndexedFields({ fields }: { fields: DBFieldAttribute[] }) {
	return fields.filter((field) => field.index && !field.unique && field.fieldName !== "id");
}

/**
 * Uses the same portable, UTF-8 byte budget and stable suffix as core's
 * getDatabaseFieldIndexName, without requiring the docs copier to load core.
 */
export function getFieldIndexName(tableName: string, fieldName: string) {
	const name = `${tableName}_${fieldName}_idx`;
	const encoder = new TextEncoder();
	if (encoder.encode(name).length <= 63) return name;

	let hash = 0x811c9dc5;
	for (let index = 0; index < name.length; index++) {
		hash ^= name.charCodeAt(index);
		hash = Math.imul(hash, 0x01000193);
	}
	const suffix = `_${(hash >>> 0).toString(16).padStart(8, "0")}_idx`;
	let prefix = "";
	let bytes = encoder.encode(suffix).length;
	for (const character of name.slice(0, -4)) {
		bytes += encoder.encode(character).length;
		if (bytes > 63) break;
		prefix += character;
	}
	return `${prefix}${suffix}`;
}

/** Quotes a database identifier for the selected SQL dialect. */
export function quoteIdentifier(value: string, dialect: import("./types").DefaultDialects) {
	if (dialect === "mysql") return `\`${value.replaceAll("`", "``")}\``;
	if (dialect === "mssql") return `[${value.replaceAll("]", "]]")}]`;
	return `"${value.replaceAll('"', '""')}"`;
}

/** Quotes a SQL string literal, including catalog lookups and dynamic DDL. */
export function quoteSQLString(value: string) {
	return `'${value.replaceAll("'", "''")}'`;
}

/** Creates guarded index DDL after the table's columns have been declared. */
export function getIndexStatements(
	ctx: import("./types").ResolverHandlerContext,
	dialect: import("./types").DefaultDialects,
) {
	const tableName = ctx.schema.modelName;
	const table = quoteIdentifier(tableName, dialect);
	return filterIndexedFields(ctx.schema).map((field) => {
		const name = getFieldIndexName(tableName, field.fieldName);
		const index = quoteIdentifier(name, dialect);
		const column = quoteIdentifier(field.fieldName, dialect);
		const ddl = `CREATE INDEX ${index} ON ${table} (${column})`;
		if (dialect === "mysql") {
			return [
				`SET @better_auth_index_sql = (SELECT IF(`,
				`\tEXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = ${quoteSQLString(tableName)})`,
				`\tAND NOT EXISTS (SELECT 1 FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = ${quoteSQLString(tableName)} AND index_name = ${quoteSQLString(name)}),`,
				`\t${quoteSQLString(ddl)}, 'SELECT 1'));`,
				`PREPARE better_auth_index_stmt FROM @better_auth_index_sql;`,
				`EXECUTE better_auth_index_stmt;`,
				`DEALLOCATE PREPARE better_auth_index_stmt;`,
			].join("\n");
		}
		if (dialect === "mssql") {
			const object = `OBJECT_ID(N${quoteSQLString(table)}, N'U')`;
			return [
				`IF ${object} IS NOT NULL`,
				`\tAND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = ${object} AND name = N${quoteSQLString(name)})`,
				`BEGIN`,
				`\t${ddl};`,
				`END;`,
			].join("\n");
		}
		return `CREATE INDEX IF NOT EXISTS ${index} ON ${table} (${column});`;
	});
}
