import type {
	DBFieldAttribute,
	Resolver,
	ResolverHandlerContext,
} from "../types";
import { filterForeignKeys, getIndexStatements, getTypeFactory, quoteIdentifier, quoteSQLString } from "../utils";

type CustomResolverContext = ResolverHandlerContext & {
	getType: ReturnType<typeof getTypeFactory>;
};

const formatField = (field: DBFieldAttribute, ctx: CustomResolverContext) => {
	let out = `${quoteIdentifier(field.fieldName, "mssql")} ${ctx.getType(field)}`;

	if (field.required !== false) {
		out += " NOT NULL";
	}

	if (field.fieldName === "id") {
		out += " PRIMARY KEY";
	}

	if (field.unique) {
		out += " UNIQUE";
	}

	out += ",";
	return out;
};

const formatForeignKey = (field: DBFieldAttribute) => {
	let newLine = `FOREIGN KEY (${quoteIdentifier(field.fieldName, "mssql")}) REFERENCES ${quoteIdentifier(field.references!.model, "mssql")}(${quoteIdentifier(field.references!.field, "mssql")})`;

	if (field.references!.onDelete) {
		newLine += ` ON DELETE ${field.references!.onDelete.toUpperCase()}`;
	}

	newLine += ",";
	return newLine;
};

export const mssqlResolver = {
	handler: (ctx) => {
		const getType = getTypeFactory((field) => ({
			string:
				field.unique || field.sortable || field.index
					? "varchar(255)"
					: field.references
						? "varchar(36)"
						: "varchar(8000)",
			boolean: "smallint",
			number: field.bigint ? "bigint" : "integer",
			date: "datetime2(3)",
			json: "varchar(8000)",
			id: ctx.useNumberId ? "integer" : "varchar(36)",
			foreignKeyId: ctx.useNumberId ? "integer" : "varchar(36)",
		}));
		const lines = [
			`IF OBJECT_ID(${quoteSQLString(quoteIdentifier(ctx.schema.modelName, 'mssql'))}, 'U') IS ${ctx.mode === "create" ? "NULL" : "NOT NULL"}`,
			"BEGIN",
			ctx.mode === "create"
				? `\tCREATE TABLE ${quoteIdentifier(ctx.schema.modelName, "mssql")} (`
				: `\tALTER TABLE ${quoteIdentifier(ctx.schema.modelName, "mssql")}`,
		];
		const fields = [];
		for (const field of ctx.schema.fields) {
			fields.push(
				`\t\t${ctx.mode === "alter" ? "ADD " : ""}${formatField(field, {
