			const indexes = filterIndexedFields(ctx.schema);
			if (indexes.length) {
				table.push("}, (table) => [");
				for (const field of indexes) {
					const name = getFieldIndexName(
						tableName,
						convertToSnakeCase(field.fieldName, options.camelCase),
					);
					table.push(
						`\tt.index(${JSON.stringify(name)}).on(table.${field.fieldName}),`,
					);
				}
				table.push("]);");
			} else {
				table.push("});");
			}

			return [...imports, "", ...table].join("\n");
		},
	};
};
"}
